import{R as e,e as o,f as i,U as n}from"./chunks/framework.ywem4qy5.js";const d=JSON.parse('{"title":"ClickUp","description":"","frontmatter":{},"headers":[],"relativePath":"integrations/miscellaneous/clickup.md","filePath":"integrations/miscellaneous/clickup.md","lastUpdated":1775908585000}'),a={name:"integrations/miscellaneous/clickup.md"};function l(r,t,s,c,p,h){return o(),i("div",null,[...t[0]||(t[0]=[n('<h1 id="clickup" tabindex="-1">ClickUp <a class="header-anchor" href="#clickup" aria-label="Permalink to &quot;ClickUp&quot;">​</a></h1><p>Follow the below steps to connect to the ClickUp API.</p><h3 id="step-1-create-the-integration" tabindex="-1">Step 1. Create the Integration <a class="header-anchor" href="#step-1-create-the-integration" aria-label="Permalink to &quot;Step 1. Create the Integration&quot;">​</a></h3><ol><li>Navigate to <strong>Formie</strong> → <strong>Settings</strong> → <strong>CRM</strong>.</li><li>Click the <strong>New Integration</strong> button.</li><li>Select ClickUp as the <strong>Integration Provider</strong>.</li></ol><h3 id="step-2-connect-to-the-clickup-api" tabindex="-1">Step 2. Connect to the ClickUp API <a class="header-anchor" href="#step-2-connect-to-the-clickup-api" aria-label="Permalink to &quot;Step 2. Connect to the ClickUp API&quot;">​</a></h3><ol><li>Go to <a href="https://app.clickup.com" target="_blank">ClickUp</a> and login to your account.</li><li>Click on your profile dropdown on the top-right of the screen, and select <strong>Settings</strong>.</li><li>In the left-hand sidebar, click <strong>Apps</strong>.</li><li>Click the <strong>Generate</strong> button.</li><li>Copy the <strong>API Token</strong> from ClickUp and paste in the <strong>API Key</strong> field in Formie.</li><li>Copy the <strong>Workspace ID</strong> from ClickUp&#39;s URL. e.g. <code>https://app.clickup.com/**9016531**</code></li></ol><h3 id="step-3-test-connection" tabindex="-1">Step 3. Test Connection <a class="header-anchor" href="#step-3-test-connection" aria-label="Permalink to &quot;Step 3. Test Connection&quot;">​</a></h3><ol><li>Save this integration.</li><li>Click on the <strong>Refresh</strong> button in the right-hand sidebar.</li></ol><h3 id="step-4-form-setting" tabindex="-1">Step 4. Form Setting <a class="header-anchor" href="#step-4-form-setting" aria-label="Permalink to &quot;Step 4. Form Setting&quot;">​</a></h3><ol><li>Go to the form you want to enable this integration on.</li><li>Click the <strong>Integrations</strong> tab.</li><li>In the left-hand sidebar, select the name you gave the integration.</li><li>Enable the integration and fill out all required fields.</li><li>Click <strong>Save</strong> to save the form.</li></ol>',10)])])}const u=e(a,[["render",l]]);export{d as __pageData,u as default};
